from pathlib import Path
import json,gzip,hashlib,datetime,re,subprocess,shutil
out=Path('00_nucleo/diagnosticos/tekt-v16-introspect-origins-2026-10-16');scope=json.load(open(out/'scope.json'));mat=json.load(open(out/'materialization.json'));source=Path('01_core/src/compiler/layout/realized.rs');owner=Path('00_nucleo/prompts/compiler/layout/realized.md');now=lambda:datetime.datetime.now(datetime.timezone.utc).isoformat();sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
rows=json.loads((out/'preview-architecture.log').read_text())['runs'][0]['results'];notes=[x for x in rows if x['ruleId']=='V20' and x['locations'][0]['physicalLocation']['artifactLocation']['uri']=='./'+str(source)];assert len(notes)==1
receipt={'utc':now(),'source_before':source.read_text(),'owner_before':owner.read_text(),'source_sha256':sha(source),'owner_sha256':sha(owner),'measurement':notes,'head':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'diffstat':subprocess.check_output(['git','diff','HEAD','--stat'],text=True)}
with gzip.open(out/'flattening-before.json.gz','wt') as f:json.dump(receipt,f)
old='o binding other passa a capturar somente o complemento nominal em other @ (...)';new='o complemento nominal usa o parâmetro node já disponível no corpo, sem captura adicional'
text=owner.read_text();assert text.count(old)==1;text=text.replace(old,new,1)
text+='\n### Refinamento medido de sintaxe plana\n\npreview-architecture.log e flattening-before.json.gz preservam o estado inicial desta materialização, HEAD/árvore/UTC, e o único V20 novo em realized.rs:155: profundidade 3 da captura other @ (grupo nominal). Substituir somente essa captura pela enumeração nominal plana e reutilizar node no corpo, alpha-renomeando needs_fresh_index(other)/extract_payload(other) para node. Não criar helper, descartar variantes ou alterar curto-circuito; a barreira de evolução permanece. Isso supersede a opção de captura anteriormente descrita; V19 continua informativo, V20 não deve aumentar. O L0 deste refinamento precede o ajuste do código.\n';owner.write_text(text)
(out/'l0-refinement.json').write_text(json.dumps({'utc':now(),'owners':{str(owner):text},'sha256':sha(owner),'reason':'flat nominal pattern reuses existing scrutinee, preserves calls and exhaustiveness'},indent=2)+'\n')
row=next(x for x in mat['changes'] if x['id']=='I3');body=row['before'];old='            other => {';assert body.count(old)==1
group='\n            | '.join(spelling for name,spelling in scope['variants']['Content'].items() if name not in ['Located','Realized'])
after=body.replace(old,'            '+group+' => {',1).replace('needs_fresh_index(other)','needs_fresh_index(node)').replace('extract_payload(other)','extract_payload(node)')
current=source.read_text();matches=list(re.finditer(r'^fn prepared_locations\(',current,re.M));assert len(matches)==1;start=matches[0].start();opening=current.index('{',matches[0].end());depth=1;end=opening+1
while depth:depth+=(current[end]=='{')-(current[end]=='}');end+=1
source.write_text(current[:start]+after+current[end:]);subprocess.run(['rustfmt','--edition','2021','--config','skip_children=true',str(source)],check=True)
shutil.copyfile(out/'materialization.json',out/'materialization-before-flat.json');row['after']=after;mat['files'][str(source)]['expected_after']=source.read_text();mat['flat_pattern_refinement_utc']=now();(out/'materialization.json').write_text(json.dumps(mat,ensure_ascii=False,indent=2)+'\n')
p=out/'workers/guard.py';t=p.read_text();old="for owner in scope['owners']:assert normowner(Path(owner).read_text())==normowner(baseline['files'][owner]),owner";new="expected_owners={p:baseline['files'][p] for p in scope['owners']}\nrefinement=out/'l0-refinement.json'\nif refinement.exists():expected_owners.update(json.load(open(refinement))['owners'])\nfor owner in scope['owners']:assert normowner(Path(owner).read_text())==normowner(expected_owners[owner]),owner";assert t.count(old)==1;p.write_text(t.replace(old,new,1))
print(json.dumps({'flat_refinement':True,'nominal_exhaustiveness_preserved':True,'calls_preserved_by_alpha_renaming':True}),flush=True)
